     1→# ABOUTME: Constant value node in the IR graph
     2→# ABOUTME: Represents compile-time constant values (integers, strings, etc.)
     3→use 5.42.0;
     4→use experimental qw(class);
     5→use utf8;
     6→
     7→class Chalk::IR::Node::Constant :isa(Chalk::IR::Node::Base) {
     8→    field $value :param :reader;
     9→    field $type  :param :reader;
    10→
    11→    method op() { 'Constant' }
    12→
    13→    method to_hash() {
    14→        return {
