method build_if_node($condition_node) {
    my $node_id = $self->next_node_id();
    my $if_node = Chalk::IR::Node::If->new(
        id            => $node_id,
        inputs        => [$current_control, $condition_node->id],
        condition_id  => $condition_node->id,
